E("es-u3-313-q04",3,["EA12.3.13"],2,"var",varset([function(){return mcq("To what is a magma's viscosity most directly related?","Its silica content",["Its age","Its colour","Its depth"],"Silica content controls viscosity: silica-rich felsic magma is thick and resistant to flow, while silica-poor mafic magma is runny.",{});}]),["It is a property of the magma's chemistry."]);

