E("es-u3-315-q02",3,["EA12.3.15"],2,"var",varset([function(){return mcq("Which best describes a similarity between pumice and obsidian?","composed of volcanic glass",["coarse grained textures","formed from felsic magma","formed from mafic magma"],"Pumice and obsidian are both composed of volcanic glass, formed when lava cools too quickly for crystals to grow.",{});}]),["One is frothy and one is solid, but both are glass."]);
E("es-u3-315-q03",3,["EA12.3.15"],2,"var",varset([function(){var q=mcq("At which location will the finest grained igneous rocks be found?","D",["A","B","C"],"The finest grains form where lava cools fastest, at the surface flow, location D. The dike at C cools more slowly underground, and A is a deep intrusive body.",{});q.figure='<img src="banks/earth-3209/assets/u3-315-aug07-27.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Fastest cooling gives the smallest crystals."]);

/* ----- EA12.3.16: Describe igneous rock textures ----- */
E("es-u3-316-q01",3,["EA12.3.16"],1,"var",varset([function(){var q=mcq("The igneous rock below shows a texture consisting of large crystals surrounded by a matrix of smaller crystals. What is the texture of this rock?","porphyritic",["coarse grained","fine grained","pegmatitic"],"Large crystals set in a finer matrix is a porphyritic texture, the record of two cooling stages: slow growth underground, then a faster finish.",{});q.figure='<img src="banks/earth-3209/assets/u3-316-aug07-28.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Two crystal sizes means two cooling rates."]);
E("es-u3-316-q02",3,["EA12.3.16"],2,"var",varset([function(){return mcq("Which rock-forming process will result in a glassy texture?","rapid cooling of lava at Earth’s surface",["alignment of minerals as a result of stress","cementing together of large, angular crystals","recrystallization of a rock during metamorphism"],"A glassy texture results from rapid cooling of lava at Earth's surface, so fast that no crystals form at all, as in obsidian.",{});}]),["Glassy means crystals never had time to form."]);
E("es-u3-316-q03",3,["EA12.3.16"],2,"var",varset([function(){return mcq("What is the origin of fine-grained igneous rock?","lava that cooled quickly on Earth’s surface",["lava that cooled slowly on Earth’s surface","silt that settled quickly in ocean water","silt that settled slowly in ocean water"],"Fine-grained igneous rock is lava that cooled quickly on Earth's surface, leaving only small crystals.",{});}]),["Fine grains point to lava, not magma."]);
E("es-u3-316-q04",3,["EA12.3.16"],2,"var",varset([function(){var q=mcq("Based on the diagram below of an igneous rock, which rate of cooling matches its texture? Crystals","rapid and fine grained",["rapid and coarse grained","slow and coarse grained","slow and fine grained"],"The diagram shows small, fine crystals, which form when lava cools rapidly at the surface, so the match is rapid cooling and fine grained.",{});q.figure='<img src="banks/earth-3209/assets/u3-316-aug09-20.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Small crystals mean the melt had little time to grow them."]);

/* ----- EA12.3.17: Describe how cooling rate and mineral composition determine rock types based on Bowen’s reaction series ----- */
E("es-u3-317-q01",3,["EA12.3.17"],2,"var",varset([function(){return mcq("Which mineral is found in a greater percentage in andesite than in rhyolite?","plagioclase",["biotite","orthoclase","quartz"],"Moving from rhyolite to andesite, the melt becomes more mafic and plagioclase feldspar increases, while quartz, orthoclase and biotite decrease.",{});}]),["Compare the two rocks on the composition chart."]);
E("es-u3-317-q02",3,["EA12.3.17"],1,"var",varset([function(){var q=mcq("Based on the diagram below, which mineral is found in most igneous rocks?","plagioclase feldspar",["biotite","olivine","potassium feldspar"],"Plagioclase feldspar spans the widest band on the composition chart, appearing in nearly every igneous rock type from granite to peridotite.",{});q.figure='<img src="banks/earth-3209/assets/u3-317-aug08-21.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Find the mineral whose band crosses the most rock columns."]);
E("es-u3-317-q03",3,["EA12.3.17"],2,"var",varset([function(){return mcq("According to Bowen's reaction series, igneous rocks made mainly of feldspar and quartz, the last minerals to crystallize from a cooling magma, have which composition?","Granitic (felsic)",["Basaltic (mafic)","Intermediate","Ultramafic"],"Quartz and feldspar crystallize last, at the lowest temperatures in Bowen's series, and rocks built from them have a granitic, or felsic, composition.",{});}]),["The last minerals to form are the light-coloured, silica-rich ones."]);
E("es-u3-317-q04",3,["EA12.3.17"],3,"var",varset([function(){return mcq("A basaltic magma begins to crystallize. Using Bowen's reaction series, which minerals crystallize first, and what happens to the composition of the magma that remains?","Olivine and calcium-rich plagioclase crystallize first, leaving the remaining magma richer in silica.",["Quartz and potassium feldspar crystallize first, leaving the remaining magma richer in iron.","Olivine and calcium-rich plagioclase crystallize first, leaving the remaining magma richer in iron and magnesium.","Quartz and potassium feldspar crystallize first, leaving the remaining magma richer in silica."],"Bowen's series starts at the highest temperatures with olivine and calcium-rich plagioclase. Removing those iron, magnesium and calcium-rich crystals leaves the leftover melt progressively richer in silica, which is how one parent magma can produce a range of rock types.",{});}]),["The first crystals are the high-temperature, mafic ones; removing them changes what is left behind."]);

/* ----- EA12.3.18: Identify igneous rocks based on mineral composition and texture ----- */
E("es-u3-318-q01",3,["EA12.3.18"],2,"var",varset([function(){return mcq("Which rock type is matched to the correct characteristics? Rock Type Silica Content Crystal Content","Granite: high silica, large crystals",["Basalt: high silica, large crystals","Gabbro: low silica, small crystals","Rhyolite: low silica, small crystals"],"Granite is a high-silica rock with large, coarse crystals from slow cooling underground. Basalt is low silica, gabbro has small crystals only in its extrusive pair, and rhyolite is high silica.",{});}]),["Check both columns for each row."]);
E("es-u3-318-q02",3,["EA12.3.18"],1,"var",varset([function(){return mcq("Which igneous rock is matched with its correct texture? Rock Texture","Granite: coarse",["Basalt: glassy","Obsidian: fine","Rhyolite: porphyritic"],"Granite is coarse grained from slow cooling at depth. Basalt is fine grained rather than glassy, obsidian is glassy rather than fine, and rhyolite is fine grained unless it carries phenocrysts.",{});}]),["Match each rock to the texture its cooling history produces."]);
E("es-u3-318-q03",3,["EA12.3.18"],3,"var",varset([function(){var q=mcq("Using the description and diagram below, which is the rock’s classification and type? • coarse-grained • 20 % olivine • 50 % pyroxene • 30 % calcium-rich plagioclase feldspar","mafic and gabbro",["felsic and granite","felsic and rhyolite","mafic and basalt"],"Olivine, pyroxene and calcium-rich plagioclase are the mafic minerals, and the coarse grain size means the rock cooled slowly underground. The mafic intrusive rock is gabbro.",{});q.figure='<img src="banks/earth-3209/assets/u3-318-aug09-21.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Composition first (mafic), then grain size (intrusive)."]);

