E("es-u3-319-q01",3,["EA12.3.19"],2,"var",varset([function(){return mcq("Based on the statement below, which is the correct match between mineral and rock type? Beneath a circular lake is a carrot-shaped deposit of ultramafic composition. Mineral Rock Type","diamond kimberlite",["diamond gabbro","gold gabbro","gold kimberlite"],"A carrot-shaped ultramafic pipe beneath a circular lake (a kimberlite pipe) is the host rock for diamonds, so the match is diamond and kimberlite.",{});}]),["The carrot-shaped pipe is the signature of one rock type."]);
E("es-u3-319-q02",3,["EA12.3.19"],1,"var",varset([function(){return mcq("Which description best fits a kimberlite pipe?","A carrot-shaped volcanic pipe that narrows with depth",["A horizontal sheet that spreads between rock layers","A large dome of granite crystallized at depth","A wide crater filled with layered ash"],"Kimberlite reaches the surface in carrot-shaped pipes: wide near the surface crater and narrowing downward toward the deep source.",{});}]),["Picture the shape of the deposit beneath a circular kimberlite lake."]);
E("es-u3-319-q03",3,["EA12.3.19"],2,"var",varset([function(){return mcq("Why are diamonds found in kimberlite rather than in ordinary volcanic rocks?","Kimberlite magma rises so quickly from deep in the mantle that the diamonds it carries survive the trip to the surface.",["Kimberlite lava is cooler than other lavas, so diamonds crystallize in it as it flows.","Kimberlite pipes form inside diamond-bearing sedimentary rocks near the surface.","Diamonds are washed into kimberlite pipes by rivers after the eruptions end."],"Diamonds form only under the extreme pressure found deep in the mantle. Kimberlite magma originates at those depths and erupts so rapidly that the diamond crystals are carried up before they can change into graphite.",{});}]),["Think about where diamonds can form and what a slow trip upward would do to them."]);

/* ----- EA12.3.20: Describe the origin and process of formation of sedimentary rocks ----- */
E("es-u3-320-q01",3,["EA12.3.20"],2,"var",varset([function(){var q=mcq("Which sedimentary feature is shown below?","graded bedding",["cross bedding","mud cracks","ripple marks"],"The diagram shows graded bedding: coarse grains settled at the bottom of the layer and progressively finer grains toward the top, the record of a slowing current.",{});q.figure='<img src="banks/earth-3209/assets/u3-320-jun07-28.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Look at how grain size changes from bottom to top."]);
E("es-u3-320-q02",3,["EA12.3.20"],2,"var",varset([function(){return mcq("What can be used to determine current direction?","cross bedding",["fossils","mud cracks","varves"],"Cross bedding forms as currents shift sediment, and the inclined layers lean in the direction the current was moving, so cross bedding reveals current direction.",{});}]),["One of these features is built by moving water or wind."]);
E("es-u3-320-q03",3,["EA12.3.20"],2,"var",varset([function(){return mcq("Which is the correct sequence in the formation of sedimentary rock?","weathering → erosion → deposition → compaction → cementation",["compaction → deposition → weathering → cementation → erosion","deposition → erosion → cementation → weathering → compaction","erosion → weathering → deposition → cementation → compaction"],"Sedimentary rock forms in order: weathering breaks rock down, erosion moves the sediment, deposition lays it down, then compaction and cementation turn it to rock.",{});}]),["Start with the breakdown of the source rock."]);
E("es-u3-320-q04",3,["EA12.3.20"],2,"var",varset([function(){return mcq("Quartz sandstone is held together with a cement that causes the rock to appear red. Which is the chemical composition of the cement?","Fe2O3",["CaCO3","MnO","SiO2"],"The red colour of the cement comes from iron oxide, Fe2O3, which coats and binds the quartz grains. Hematite cement is a common cause of red sandstone.",{});}]),["Red rock points to one element in the cement."]);
E("es-u3-320-q05",3,["EA12.3.20"],2,"var",varset([function(){return mcq("Which is NOT a common cement in sedimentary rocks?","Gypsum",["Calcite","Iron oxide","Silica"],"The common cements that bind sediment grains are silica, calcite and iron oxide. Gypsum forms evaporite beds of its own rather than serving as a cement.",{});}]),["Three of these precipitate in the pore spaces between grains."]);

/* ----- EA12.3.21: Describe the classes of sedimentary rocks ----- */
E("es-u3-321-q01",3,["EA12.3.21"],1,"var",varset([function(){return mcq("Which rock is properly matched with its classification? Rock Classification","Halite: chemical",["Gypsum: clastic","Limestone: clastic","Sandstone: chemical"],"Halite (rock salt) precipitates from evaporating water, so it is a chemical sedimentary rock. Gypsum is also chemical, limestone is biochemical or chemical, and sandstone is clastic.",{});}]),["Which rock forms by precipitation rather than from fragments?"]);
E("es-u3-321-q02",3,["EA12.3.21"],2,"var",varset([function(){return mcq("Which rock type matches its method of classification? Rock Type Method of Classification","Clastic sedimentary: particle size and shape",["Chemical sedimentary: crystal size and composition","Extrusive igneous: biochemical and inorganic","Intrusive igneous: density and recrystallization"],"Clastic sedimentary rocks are classified by particle size and shape. Chemical sedimentary rocks are classified by composition, igneous rocks by crystal size and composition, and density plays no part in igneous classification.",{});}]),["Clastic rocks are the fragmental ones."]);
E("es-u3-321-q03",3,["EA12.3.21"],2,"var",varset([function(){var q=mcq("Which table below correctly classifies the rocks?","Clastic: A, B, C, D; Biochemical: E; Evaporite: F",["Clastic: A, B, C; Biochemical: D; Evaporite: E, F","Clastic: A, C; Biochemical: B, E; Evaporite: D, F","Clastic: A, B, F; Biochemical: E; Evaporite: C, D"],"Conglomerate, breccia, sandstone and shale (A to D) are all clastic; limestone (E) is biochemical; rock salt (F) is an evaporite, a chemical rock. Only the first table sorts them that way.",{});q.figure='<img src="banks/earth-3209/assets/u3-321-aug09-51.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Sort the six rocks first, then find the matching table."]);
E("es-u3-321-q04",3,["EA12.3.21"],1,"var",varset([function(){return mcq("Which rock is NOT a detrital (clastic) sedimentary rock?","Limestone",["Conglomerate","Sandstone","Shale","Siltstone"],"Limestone forms from dissolved material and the remains of organisms, not from transported fragments. Conglomerate, sandstone, shale and siltstone are all detrital.",{});}]),["Detrital rocks are built from fragments of older rock."]);

/* ----- EA12.3.22: Identify clastic sedimentary rocks ----- */
E("es-u3-322-q01",3,["EA12.3.22"],1,"var",varset([function(){return mcq("Which is a clastic sedimentary rock?","breccia",["gypsum","rock salt","travertine"],"Breccia is a clastic sedimentary rock, built from cemented fragments. Gypsum and rock salt are chemical rocks, and travertine is a chemical limestone.",{});}]),["Clastic means made of fragments of older rock."]);
E("es-u3-322-q02",3,["EA12.3.22"],2,"var",varset([function(){return mcq("Which rock type consists of angular particles formed from gravel deposited close to the source of weathering?","breccia",["conglomerate","sandstone","shale"],"Angular particles of gravel size, deposited close to their source, form breccia. Conglomerate's particles are rounded by longer transport.",{});}]),["Angular versus rounded is the deciding detail."]);

/* ----- EA12.3.23: Relate sediment sorting to clastic sedimentary rocks ----- */
E("es-u3-323-q01",3,["EA12.3.23"],2,"var",varset([function(){var q=mcq("What would a geologist determine from the section of sedimentary rock below?","Feldspar grains have traveled a shorter distance than other types of grains.",["Feldspar grains are harder than other types of grains.","Quartz grains are softer than other types of grains.","Quartz grains have traveled a shorter distance than other types of grains."],"In the section, the feldspar grains are still angular while the quartz grains are rounded. Feldspar is softer and weathers quickly, so angular feldspar grains cannot have travelled far; they were deposited a shorter distance from their source.",{});q.figure='<img src="banks/earth-3209/assets/u3-323-jun08-24.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Angular grains have not been transported far, and feldspar does not survive long trips."]);
E("es-u3-323-q02",3,["EA12.3.23"],1,"var",varset([function(){var q=mcq("Which diagram shows a well-sorted sediment?","",["","",""],"Diagram A shows grains that are all about the same size, which is what well sorted means. The other diagrams mix large and small grains.",{});q.figure='<img src="banks/earth-3209/assets/u3-323-jun08-26.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Well sorted means a narrow size range."]);
E("es-u3-323-q03",3,["EA12.3.23"],2,"var",varset([function(){return mcq("Which property best distinguishes sediment deposited by a river from sediment deposited by a glacier?","amount of sediment sorting",["age of fossils found in the sediment","mineral composition of the sediment","thickness of sediment layers"],"River sediment is sorted by flowing water, while a glacier deposits its load unsorted, so the amount of sorting best distinguishes the two.",{});}]),["Think about what moving water does that ice does not."]);
E("es-u3-323-q04",3,["EA12.3.23"],3,"var",varset([function(){return mcq("A sandstone contains grains that are well rounded but range widely in size from fine sand to pebbles. What does this combination indicate about the sediment's history?","The grains were transported far enough to be rounded, but were deposited by an agent, such as a glacier or debris flow, that did not sort them by size.",["The grains were deposited close to their source, where a fast, turbulent river rounded them quickly but had no time to sort them by size.","The grains were transported a long distance by a steady river that rounded them by abrasion and sorted them thoroughly on the way.","The grains formed in place where the bedrock weathered, so no transporting agent ever moved, rounded or arranged them."],"Rounding records a long transport history, but the wide size range shows poor sorting. Running water rounds and sorts together, so the mismatch points to an agent like ice or a debris flow, which carries all sizes and drops them together.",{});}]),["Treat rounding and sorting as two separate pieces of evidence."]);

