E("es-u3-334-q02",3,["EA12.3.34"],3,"var",varset([function(){var q=mcq("If the magma chamber in the diagram below is granitic and the continental crust at “X” is granite, which type of metamorphic rock would be found at “Y” and which extrusive igneous rock would form during an eruption occurring at “Z”? Metamorphic Rock at Extrusive Igneous Rock “Y” at “Z”","Metamorphic rock at Y: gneiss; Extrusive igneous rock at Z: rhyolite",["Metamorphic rock at Y: gneiss; Extrusive igneous rock at Z: basalt","Metamorphic rock at Y: marble; Extrusive igneous rock at Z: basalt","Metamorphic rock at Y: marble; Extrusive igneous rock at Z: rhyolite"],"Granite metamorphosed by the heat of the magma chamber becomes gneiss at Y, and the granitic (felsic) magma erupting at Z cools as rhyolite, its extrusive equivalent.",{});q.figure='<img src="banks/earth-3209/assets/u3-334-final-27.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Y takes the parent rock (granite) plus heat; Z takes the magma type (granitic) to the surface."]);
